namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<Course> Courses { get; set; } = [];
}

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public Instructor Instructor { get; set; } = new();
    public bool IsFeatured { get; set; }
    public int MaxEnrollment { get; set; }
    public int CurrentEnrollment { get; set; }
}

public class Instructor
{
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string OfficeHours { get; set; } = string.Empty;
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments =
        [
            new Department { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new Department { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new Department { Id = 3, Code = "ENG", Name = "English", Description = "Study of literature, writing, and language." },
            new Department { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new Department { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and human civilization." },
        ];

        _courses =
        [
            new Course
            {
                Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming",
                Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, methods, and object-oriented design. No prior experience required.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201",
                DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true, MaxEnrollment = 30, CurrentEnrollment = 22,
                Instructor = new Instructor { Name = "Dr. Sarah Chen", Title = "Associate Professor", Email = "schen@university.edu", Bio = "Dr. Chen has 12 years of experience teaching introductory programming. She earned her Ph.D. from MIT and specializes in CS education research.", OfficeHours = "Tue/Thu 2:00–4:00 PM, Science Hall 305" }
            },
            new Course
            {
                Id = 2, CourseCode = "CS 301", Title = "Data Structures and Algorithms",
                Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms).",
                Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Location = "Science Hall 105",
                DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true, MaxEnrollment = 25, CurrentEnrollment = 25,
                Instructor = new Instructor { Name = "Dr. James Park", Title = "Professor", Email = "jpark@university.edu", Bio = "Dr. Park is a leading researcher in algorithm design with over 50 published papers. Previously worked at Google Research.", OfficeHours = "Mon/Wed 1:00–3:00 PM, Science Hall 310" }
            },
            new Course
            {
                Id = 3, CourseCode = "CS 450", Title = "Machine Learning",
                Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and model evaluation techniques.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Science Hall 301",
                DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false, MaxEnrollment = 20, CurrentEnrollment = 18,
                Instructor = new Instructor { Name = "Dr. Sarah Chen", Title = "Associate Professor", Email = "schen@university.edu", Bio = "Dr. Chen has 12 years of experience teaching introductory programming. She earned her Ph.D. from MIT and specializes in CS education research.", OfficeHours = "Tue/Thu 2:00–4:00 PM, Science Hall 305" }
            },
            new Course
            {
                Id = 4, CourseCode = "MATH 201", Title = "Calculus II",
                Description = "Continuation of single-variable calculus covering techniques of integration, infinite series, parametric equations, and polar coordinates.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Building 102",
                DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true, MaxEnrollment = 35, CurrentEnrollment = 28,
                Instructor = new Instructor { Name = "Dr. Michael Torres", Title = "Professor", Email = "mtorres@university.edu", Bio = "Dr. Torres has taught calculus for 20 years and authored two widely-used textbooks on analysis.", OfficeHours = "Mon/Wed/Fri 11:00 AM–12:00 PM, Math Building 210" }
            },
            new Course
            {
                Id = 5, CourseCode = "MATH 310", Title = "Linear Algebra",
                Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to systems of equations.",
                Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Math Building 205",
                DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false, MaxEnrollment = 30, CurrentEnrollment = 19,
                Instructor = new Instructor { Name = "Dr. Lisa Wang", Title = "Assistant Professor", Email = "lwang@university.edu", Bio = "Dr. Wang joined the department in 2022 after completing postdoctoral research at Stanford. Her work focuses on computational algebra.", OfficeHours = "Tue/Thu 3:00–5:00 PM, Math Building 208" }
            },
            new Course
            {
                Id = 6, CourseCode = "ENG 101", Title = "Composition and Rhetoric",
                Description = "Develop essential skills in academic writing, argumentation, and critical analysis of texts across genres.",
                Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Humanities 110",
                DepartmentId = 3, DepartmentName = "English", IsFeatured = false, MaxEnrollment = 25, CurrentEnrollment = 20,
                Instructor = new Instructor { Name = "Prof. David Miller", Title = "Senior Lecturer", Email = "dmiller@university.edu", Bio = "Prof. Miller is an award-winning writing instructor with published works in composition pedagogy.", OfficeHours = "Mon/Wed 12:00–1:30 PM, Humanities 205" }
            },
            new Course
            {
                Id = 7, CourseCode = "ENG 340", Title = "American Literature: 1865–Present",
                Description = "Survey of American literary works from the post-Civil War era to the contemporary period, examining themes of identity, modernism, and social change.",
                Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Location = "Humanities 215",
                DepartmentId = 3, DepartmentName = "English", IsFeatured = true, MaxEnrollment = 20, CurrentEnrollment = 14,
                Instructor = new Instructor { Name = "Dr. Angela Brooks", Title = "Associate Professor", Email = "abrooks@university.edu", Bio = "Dr. Brooks specializes in 20th-century American fiction with a focus on the Harlem Renaissance and postmodern narratives.", OfficeHours = "Tue 11:00 AM–1:00 PM, Humanities 310" }
            },
            new Course
            {
                Id = 8, CourseCode = "PHYS 201", Title = "Classical Mechanics",
                Description = "Newtonian mechanics, conservation laws, oscillations, and rotational dynamics with applications to real-world systems.",
                Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Location = "Physics Lab 101",
                DepartmentId = 4, DepartmentName = "Physics", IsFeatured = false, MaxEnrollment = 30, CurrentEnrollment = 24,
                Instructor = new Instructor { Name = "Dr. Robert Kim", Title = "Professor", Email = "rkim@university.edu", Bio = "Dr. Kim has 15 years of experience in physics education and runs the department's undergraduate research lab.", OfficeHours = "Wed/Fri 2:00–3:30 PM, Physics Lab 204" }
            },
            new Course
            {
                Id = 9, CourseCode = "PHYS 305", Title = "Quantum Mechanics",
                Description = "Introduction to quantum theory: wave functions, Schrödinger equation, operators, angular momentum, and hydrogen atom.",
                Credits = 3, Schedule = "Tue/Thu 2:30–3:50 PM", Location = "Physics Lab 301",
                DepartmentId = 4, DepartmentName = "Physics", IsFeatured = true, MaxEnrollment = 20, CurrentEnrollment = 16,
                Instructor = new Instructor { Name = "Dr. Elena Volkov", Title = "Associate Professor", Email = "evolkov@university.edu", Bio = "Dr. Volkov is a theoretical physicist whose research focuses on quantum information theory. She received the university's teaching excellence award in 2024.", OfficeHours = "Thu 4:00–6:00 PM, Physics Lab 303" }
            },
            new Course
            {
                Id = 10, CourseCode = "HIST 150", Title = "World Civilizations",
                Description = "A global survey of major civilizations from antiquity to the early modern period, exploring cultural exchange, political systems, and economic development.",
                Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", Location = "Liberal Arts 120",
                DepartmentId = 5, DepartmentName = "History", IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 32,
                Instructor = new Instructor { Name = "Dr. Patricia Nguyen", Title = "Professor", Email = "pnguyen@university.edu", Bio = "Dr. Nguyen is a specialist in comparative world history with field research experience across Southeast Asia and Europe.", OfficeHours = "Mon 5:00–6:30 PM, Liberal Arts 305" }
            },
        ];

        foreach (var dept in _departments)
        {
            dept.Courses = _courses.Where(c => c.DepartmentId == dept.Id).ToList();
        }
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        var course = GetCourse(request.CourseId);
        if (course == null) return false;
        // In a real app this would persist to a database
        return true;
    }
}

