@page "/courses"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" class="search-form">
    <input type="text" name="search" value="@Search" placeholder="Search by title, code, or instructor..." class="search-input" />
    <select name="departmentId" class="filter-select">
        <option value="">All Departments</option>
        @foreach (var dept in Catalog.GetDepartments())
        {
            <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
        }
    </select>
    <button type="submit" class="btn btn-primary">Search</button>
</form>

@{
    var courses = Catalog.GetCourses(Search, DepartmentId);
}

<p class="results-count">Showing @courses.Count course(s)</p>

@if (courses.Count == 0)
{
    <p class="no-results">No courses match your search criteria. Try broadening your search.</p>
}
else
{
    <div class="course-list">
        @foreach (var course in courses)
        {
            <div class="course-list-item">
                <div class="course-list-header">
                    <span class="badge">@course.CourseCode</span>
                    <h3><a href="/courses/@course.Id">@course.Title</a></h3>
                </div>
                <p class="course-meta">
                    @course.DepartmentName &middot; @course.Credits credits &middot; @course.Instructor.Name
                </p>
                <p>@course.Schedule &middot; @course.Location</p>
                <p class="enrollment-status">
                    Enrolled: @course.CurrentEnrollment / @course.MaxEnrollment
                    @if (course.CurrentEnrollment >= course.MaxEnrollment)
                    {
                        <span class="full-badge">FULL</span>
                    }
                </p>
            </div>
        }
    </div>
}

@code {
    [SupplyParameterFromQuery]
