arguments.new_str:
@page "/enroll"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Submit a request to enroll in a course. You will receive confirmation via your university email.</p>

@if (submitted)
{
    <div class="success-message">
        <h2>Request Submitted Successfully</h2>
        <p>Your enrollment request has been received. You will be notified of your enrollment status via email.</p>
        <a href="/courses" class="btn btn-primary">Back to Course Catalog</a>
    </div>
}
else
{
    if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="error-message">
            <p>@errorMessage</p>
        </div>
    }

    <form method="post" class="enroll-form">
        <AntiforgeryToken />

        <div class="form-group">
            <label for="studentName">Full Name</label>
            <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName" required />
        </div>

        <div class="form-group">
            <label for="studentId">Student ID</label>
            <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" required placeholder="e.g., STU-12345" />
        </div>

        <div class="form-group">
            <label for="courseId">Course</label>
            <select id="courseId" name="Model.CourseId" required>
                <option value="">-- Select a course --</option>
                @foreach (var course in Catalog.GetCourses())
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">
                        @course.CourseCode - @course.Title (@course.CurrentEnrollment/@course.MaxEnrollment enrolled)
                    </option>
                }
            </select>
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
    </form>
}

@code {
    [SupplyParameterFromForm]
    public EnrollmentRequest? Model { get; set; }

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private bool submitted;
    private string? errorMessage;

    protected override void OnInitialized()
    {
        Model ??= new EnrollmentRequest();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        if (Model is not null && !string.IsNullOrWhiteSpace(Model.StudentName)
            && !string.IsNullOrWhiteSpace(Model.StudentId) && Model.CourseId > 0)
        {
            var success = Catalog.SubmitEnrollmentRequest(Model);
            if (success)
            {
                submitted = true;
            }
            else
            {
                errorMessage = "The selected course was not found. Please try again.";
            }
        }
    }
}

